import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { resolve } from "node:path";
import { isDeepStrictEqual } from "node:util";
import { gunzipSync } from "node:zlib";

const p = import.meta.dir;
const root = resolve(p, "../barrel-forecast-model-mixture-20261117/v10-functional");
const analysis = JSON.parse(readFileSync(resolve(root, "qualification-analysis.json"), "utf8"));
assert.equal(analysis.complete, true);
assert.equal(analysis.families, 756);
assert.equal(analysis.fights, 12096);
const details = JSON.parse(gunzipSync(readFileSync(resolve(p, "legacy-v10-decision-attribution/all-case-divergences.json.gz"))).toString());
const expected = new Map(details.map((r: any) => [`${r.board}/${r.game}`, r]));
assert.equal(expected.size, 3024);
const pairs = new Map<string, Record<string, any>>();
const hashes: Record<string, string> = {};
for (const [path, digest] of Object.entries(analysis.rawSha256)) {
    const raw = readFileSync(resolve(root, path));
    const actualDigest = createHash("sha256").update(raw).digest("hex");
    assert.equal(actualDigest, digest);
    hashes[path] = actualDigest;
    const text = path.endsWith(".gz") ? gunzipSync(raw).toString() : raw.toString();
    for (const line of text.trim().split("\n")) {
        const row = JSON.parse(line);
        if (row.mode !== "stock" && row.mode !== "mixture") continue;
        assert.equal(row.registrationSha256, analysis.registrationSha256);
        const key = `${row.board}/${row.game}`;
        const pair = pairs.get(key) ?? {};
        assert.equal(pair[row.mode], undefined);
        pair[row.mode] = row;
        pairs.set(key, pair);
    }
}
assert.equal(pairs.size, 3024);
const categories: Record<string, number> = {};
const outcomes: Record<string, number> = {};
const families = new Map<number, Set<number>>();
let halfPointDelta = 0;
for (const [key, pair] of pairs) {
    assert.deepEqual(Object.keys(pair).sort(), ["mixture", "stock"]);
    const a = pair.stock, b = pair.mixture, e: any = expected.get(key);
    assert(e);
    assert.equal(a.inputSha256, b.inputSha256);
    assert([0, .5, 1].includes(a.score) && [0, .5, 1].includes(b.score));
    const delta = b.score - a.score;
    halfPointDelta += delta * 2;
    const outcome = delta === 0 ? "unchanged" : delta > 0 ? "improved" : "worsened";
    let first: number | null = null;
    for (let i = 0; i < Math.max(a.actualTurns.length, b.actualTurns.length); i++) {
        if (!isDeepStrictEqual(a.actualTurns[i], b.actualTurns[i])) { first = i; break; }
    }
    let category: string;
    if (first === null) {
        category = a.traceSha256 === b.traceSha256 ? "identical-trace-and-recorded-decisions" : "trace-or-event-difference-with-identical-recorded-decisions";
    } else if (!a.actualTurns[first] || !b.actualTurns[first]) {
        category = "recorded-length-difference";
    } else {
        const l = a.actualTurns[first], r = b.actualTurns[first];
        const actorSame = l.unitId === r.unitId && l.creatureName === r.creatureName;
        const rawSame = isDeepStrictEqual(l.rawIncumbent, r.rawIncumbent);
        const choiceSame = isDeepStrictEqual(l.chosenDecision, r.chosenDecision);
        category = actorSame && rawSame && !choiceSame
            ? "recorded-choice-difference-with-same-actor-and-native-proposal"
            : !actorSame ? "actor-sequence-difference-before-first-recorded-choice-change"
            : !rawSame ? "native-proposal-difference-at-first-recorded-divergence"
            : "other-recorded-metadata-difference";
    }
    assert.equal(e.firstRecordedDivergenceIndex, first);
    assert.equal(e.category, category);
    assert.equal(e.outcome, outcome);
    assert.equal(e.delta, delta);
    assert.equal(e.stockScore, a.score);
    assert.equal(e.mixtureScore, b.score);
    assert.equal(e.inputSha256, a.inputSha256);
    categories[category] = (categories[category] ?? 0) + 1;
    outcomes[outcome] = (outcomes[outcome] ?? 0) + 1;
    const games = families.get(a.board) ?? new Set<number>();
    games.add(a.game); families.set(a.board, games);
}
assert.equal(families.size, 756);
for (const games of families.values()) assert.deepEqual([...games].sort(), [0, 1, 2, 3]);
const summary = JSON.parse(readFileSync(resolve(p, "legacy-v10-decision-attribution/summary.json"), "utf8"));
assert.deepEqual(categories, summary.categories);
assert.equal(outcomes.worsened, 166);
assert.equal(outcomes.improved, 208);
const output = resolve(p, "independent-legacy-decision-attribution.json");
assert(!existsSync(output));
const result = { passed: true, cases: pairs.size, families: families.size, categories, outcomes, halfPointDelta,
    scoreDelta: halfPointDelta / (2 * pairs.size), allCasesAndWorsenedOutcomesRetained: true,
    rawSha256: hashes, scope: "Independent reconstruction from completed legacy v10 raw outcomes and recorded turns only. No fresh confirmation outcomes, policy selection or new strength claim." };
writeFileSync(output, JSON.stringify(result, null, 2) + "\n", { flag: "wx" });
console.log(JSON.stringify({ ...result, rawSha256: undefined }, null, 2));

import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { isDeepStrictEqual } from "node:util";

const p = import.meta.dir, root = resolve(p, "legacy-first-root-return");
const legacy = resolve(p, "../barrel-forecast-model-mixture-20261117/v10-functional");
const json = (path: string) => JSON.parse(readFileSync(path, "utf8"));
const sha = (bytes: Buffer) => createHash("sha256").update(bytes).digest("hex");
const receipt = json(resolve(p, "legacy-root-audit-return-verification.json"));
for (const row of receipt.files) assert.equal(sha(readFileSync(resolve(root, row.path))), row.sha256);
const status = json(resolve(root, "status.json"));
assert.equal(status.complete, true); assert.deepEqual(status.errors, []);
assert.deepEqual(status.liveWorkerPids, []); assert.equal(status.fights, 48);
const registration = readFileSync(resolve(legacy, "first-root-audit-registration-v4.json"));
assert.equal(sha(registration), status.registrationSha256);
const jobs: any[] = json(resolve(legacy, "first-root-audit-cases.json"));
const expected = new Map(jobs.map(j => [`${j.board}/${j.game}`, j]));
const analysis = json(resolve(p, "legacy-root-audit-analysis.json"));
assert.equal(analysis.complete, true); assert.equal(analysis.cases, 24);
const report = new Map(analysis.casesDetail.map((r: any) => [`${r.board}/${r.game}`, r]));
const pairs = new Map<string, Record<string, any>>();
let executions = 0;
for (const file of readdirSync(root).filter(f => /^worker-\d+\.jsonl$/.test(f))) {
    for (const line of readFileSync(resolve(root, file), "utf8").trim().split("\n")) {
        const row = JSON.parse(line), key = `${row.board}/${row.game}`, job = expected.get(key);
        assert(job); assert(["stock", "mixture"].includes(row.mode));
        assert.equal(row.registrationSha256, status.registrationSha256);
        assert.equal(row.inputSha256, job.expectedInputSha256);
        assert.equal(row.traceSha256, job.expectedTraceSha256[row.mode]);
        assert.equal(row.score, job.expectedScore[row.mode]);
        assert.deepEqual(row.actualTurns, job.expectedActualTurns[row.mode]);
        assert.deepEqual(row.forecast, job.expectedForecast[row.mode]);
        assert.equal(row.root.turn, job.auditTurnIndex); assert.equal(row.root.unit.id, job.auditUnitId);
        const pair = pairs.get(key) ?? {}; assert.equal(pair[row.mode], undefined);
        pair[row.mode] = row; pairs.set(key, pair); executions++;
    }
}
assert.equal(executions, 48); assert.equal(pairs.size, 24);
const fields = ["capturePoint", "beforeNativeSnapshotSha256", "snapshotSha256", "damageStats", "actualTurnPrefixSha256", "eventPrefixSha256", "liveRandomDrawCount", "liveRandomPrefixSha256", "uuidSequence", "rawIncumbent", "unit", "lap", "turn"];
const differences: Record<string, string[]> = {}, groups: Record<string, number> = {};
let nativeOnlyCases = 0, terminalSamples = 0, fullSamples = 0;
for (const [key, pair] of pairs) {
    assert.deepEqual(Object.keys(pair).sort(), ["mixture", "stock"]);
    const a = pair.stock.root, b = pair.mixture.root, e: any = report.get(key), job = expected.get(key)!;
    assert(e);
    assert.deepEqual(e.stockDecision, pair.stock.actualTurns[job.auditTurnIndex].chosenDecision);
    assert.deepEqual(e.mixtureDecision, pair.mixture.actualTurns[job.auditTurnIndex].chosenDecision);
    const diff = fields.filter(f => !isDeepStrictEqual(a[f], b[f]));
    assert.deepEqual(diff, e.rootPrefixDifferences); if (diff.length) differences[key] = diff;
    groups[job.auditGroup] = (groups[job.auditGroup] ?? 0) + 1;
    if (a.capturePoint === "before-native-strategy-without-A19") {
        assert.equal(b.capturePoint, a.capturePoint); assert.equal(a.forecasts.length, 0); assert.equal(b.forecasts.length, 0);
        nativeOnlyCases++;
    }
    for (const mode of ["stock", "mixture"]) {
        const full = pair[mode].root.forecasts.filter((f: any) => f.horizonMode === "turns");
        const terminal = full.filter((f: any) => f.finishedSim && f.winningTeam !== null && f.exactTerminalResults);
        assert.equal(e.sampleCounts[mode].fullSamples, full.length);
        assert.equal(e.sampleCounts[mode].exactTerminalSamples, terminal.length);
        fullSamples += full.length; terminalSamples += terminal.length;
    }
}
assert.equal(Object.keys(groups).length, 4);
for (const count of Object.values(groups)) assert.equal(count, 6);
const result = { passed: true, cases: 24, executions, groups, nativeOnlyCases, fullSamples, exactTerminalSamples: terminalSamples,
    prefixFieldDifferences: differences, allOriginalInputsTracesOutcomesForecastsAndActualTurnsExact: true,
    scope: "Independent verification of selected completed legacy-bank diagnostics. No efficacy, calibration, timing or one-action causal claim; no fresh confirmation outcome read." };
const output = resolve(p, "independent-legacy-root-audit.json"); assert(!existsSync(output));
writeFileSync(output, JSON.stringify(result, null, 2) + "\n", { flag: "wx" });
console.log(JSON.stringify(result, null, 2));

import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
