const p = import.meta.dir, root = resolve(p, "target-memory-alias-return");
const legacy = resolve(p, "../barrel-forecast-model-mixture-20261117/v10-functional");
const json = (path: string) => JSON.parse(readFileSync(path, "utf8"));
const sha = (bytes: Buffer) => createHash("sha256").update(bytes).digest("hex");
const receipt = json(resolve(p, "target-memory-alias-return-verification.json"));
for (const r of receipt.files) assert.equal(sha(readFileSync(resolve(root, r.path))), r.sha256);
const status = json(resolve(root, "status.json"));
assert.equal(status.complete, true); assert.deepEqual(status.errors, []); assert.deepEqual(status.liveWorkerPids, []);
assert.equal(status.fights, 4);
assert.equal(sha(readFileSync(resolve(legacy, "target-memory-alias-audit-registration.json"))), status.registrationSha256);
const jobs: any[] = json(resolve(legacy, "target-memory-alias-audit-cases.json"));
const expected = new Map(jobs.map(j => [`${j.board}/${j.game}`, j]));
const pairs = new Map<string, Record<string, any>>();
let executions = 0;
for (const file of readdirSync(root).filter(f => /^worker-\d+\.jsonl$/.test(f))) {
    for (const line of readFileSync(resolve(root, file), "utf8").trim().split("\n")) {
        const r = JSON.parse(line), key = `${r.board}/${r.game}`, j = expected.get(key);
        assert(j); assert(["stock", "mixture"].includes(r.mode));
        assert.equal(r.registrationSha256, status.registrationSha256);
        assert.equal(r.inputSha256, j.expectedInputSha256); assert.equal(r.traceSha256, j.expectedTraceSha256[r.mode]);
        assert.equal(r.score, j.expectedScore[r.mode]); assert.deepEqual(r.forecast, j.expectedForecast[r.mode]);
        assert.deepEqual(r.actualTurns, j.expectedActualTurns[r.mode]); assert.equal(r.memoryTurns.length, r.actualTurns.length);
        const pair = pairs.get(key) ?? {}; assert.equal(pair[r.mode], undefined);
        pair[r.mode] = r; pairs.set(key, pair); executions++;
    }
}
assert.equal(executions, 4); assert.equal(pairs.size, 2);
const analysis = json(resolve(p, "target-memory-alias-analysis.json"));
const details = new Map(analysis.details.map((r: any) => [`${r.board}/${r.game}`, r]));
const found = [];
for (const [key, pair] of pairs) {
    assert.deepEqual(Object.keys(pair).sort(), ["mixture", "stock"]);
    const a = pair.stock, b = pair.mixture, e: any = details.get(key);
    assert(e);
    const firstAction = a.actualTurns.findIndex((t: any, i: number) => !isDeepStrictEqual(t, b.actualTurns[i]));
    const firstMemory = a.memoryTurns.findIndex((t: any, i: number) => !isDeepStrictEqual(new Map(t.memory), new Map(b.memoryTurns[i]?.memory)));
    assert(firstMemory >= 0 && firstAction > firstMemory);
    assert.equal(firstAction, e.firstRecordedActionDifferenceTurn); assert.equal(firstMemory, e.firstTargetMemoryDifferenceTurn);
    const left = a.memoryTurns[firstMemory], right = b.memoryTurns[firstMemory];
    assert.deepEqual(a.actualTurns[firstMemory], b.actualTurns[firstMemory]);
    assert.deepEqual(a.actualTurns[firstMemory].rawIncumbent, a.actualTurns[firstMemory].chosenDecision);
    assert.deepEqual(b.actualTurns[firstMemory].rawIncumbent, b.actualTurns[firstMemory].chosenDecision);
    assert.equal(left.rawAndChosenShareArray, e.stockRawAndChosenShareArray);
    assert.equal(right.rawAndChosenShareArray, e.mixtureRawAndChosenShareArray);
    assert.notEqual(left.rawAndChosenShareArray, right.rawAndChosenShareArray);
    found.push({ key, firstMemory, firstAction, actor: left.creatureName, stockSharesArray: left.rawAndChosenShareArray, mixtureSharesArray: right.rawAndChosenShareArray });
}
const result = { passed: true, cases: 2, executions, allOriginalControlsExact: true, identityBranchDifferenceConfirmed: found,
    scope: "Independent old-bank diagnostic verification. No corrected policy, new strength/cost estimate, one-action win causality, serving activation or fresh-confirmation change." };
const output = resolve(p, "independent-target-memory-alias-audit.json"); assert(!existsSync(output));
writeFileSync(output, JSON.stringify(result, null, 2) + "\n", { flag: "wx" });
console.log(JSON.stringify(result, null, 2));

import { getAIStrategy } from "./sources/common/src/ai";
import { MINDLESS_AI_VERSION } from "./sources/common/src/ai/unit_ai_overrides";
import { createHash } from "node:crypto";
import { snapshotBattle } from "./sources/common/src/simulation/battle_snapshot";
import { captureDeterministicRandomState } from "./sources/common/src/utils/lib";
const normalize = (value:any, seen=new Map<any,number>()):any => {
 if(value===undefined)return {$undefined:true};
 if(typeof value==="number"&&!Number.isFinite(value))return {$number:String(value)};
 if(typeof value==="bigint")return {$bigint:String(value)};
 if(typeof value==="function")return {$function:value.name};
 if(value===null||typeof value!=="object")return value;
 if(seen.has(value))return {$ref:seen.get(value)};
 const id=seen.size;seen.set(value,id);
 if(value instanceof Map)return {$id:id,$type:"Map",entries:[...value].map(([k,v])=>[normalize(k,seen),normalize(v,seen)])};
 if(value instanceof Set)return {$id:id,$type:"Set",values:[...value].map(v=>normalize(v,seen))};
 if(Array.isArray(value))return {$id:id,$type:"Array",values:value.map(v=>normalize(v,seen))};
 return {$id:id,$type:value.constructor?.name??"Object",fields:Object.fromEntries(Object.keys(value).sort().map(k=>[k,normalize(value[k],seen)]))};
};
const unitView=(u:any)=>({id:u.getId(),name:u.getName(),team:u.getTeam(),hp:u.getCumulativeHp(),alive:u.getAmountAlive(),cells:structuredClone(u.getCells()),dead:u.isDead()});
let activeRoot:any,activeSample:any;
import assert from "node:assert/strict";
import { appendFileSync } from "node:fs";
import { createInterface } from "node:readline";
import { buildChoice } from "./build-choice";
import { fightNative, hash } from "./first-root-audit-native-v3";
import { SearchDriver } from "./sources/common/src/simulation/search_driver";
import { selectBarrelForecastIntent } from "./sources/common/src/simulation/barrel_forecast_intent_research";
import { permuteRankedDraftSeed } from "./sources/common/src/simulation/ranked_draft_eval";
import { getA19NeuralModel } from "./sources/common/src/simulation/a19_neural_model";
import { loadLockedA19FullPolicyPair } from "./sources/common/src/simulation/v0_9/a19_full_policy_checkpoint";

import { selectBarrelForecastModelMixture, usesBarrelIntentForecast } from "./sources/common/src/simulation/barrel_forecast_model_mixture_research";

import { environment as qualifiedEnvironment } from "./profiles";
import { V08_A19_PROFILE_SCHEMA } from "./sources/common/src/ai/versions/v0_8_a19_profile";
assert.equal(V08_A19_PROFILE_SCHEMA,"hoc.v0_8_a19_production_profile.v10");
assert.equal(qualifiedEnvironment.SEARCH_A19_NIGHTMARE_WALL_MOVEMENT,"1");
assert.equal(qualifiedEnvironment.SEARCH_A19_MELEE_BARREL_DELIBERATION,"1");
assert.equal(qualifiedEnvironment.SEARCH_ROLLOUTS,"2");
const [output] = process.argv.slice(2), g = globalThis as any;
const proto = SearchDriver.prototype as any;
const choose = proto.chooseDecision, rollout = proto.rollout;
const model = getA19NeuralModel(), predict = model.predict, accepted = loadLockedA19FullPolicyPair();
let scope: any;
model.predict = (observation: any) => {
    if (g.__mode === "accepted" && g.__modelActorTeam === g.__team) {
        g.__acceptedCalls++;
        return accepted.predict(observation);
    }
    return predict.call(model, observation);
};
g.__auditBeforeStrategy=(unit:any,context:any)=>{
 if(context.decisionOrigin!=="root"||g.__actualTurns?.length!==g.__auditJob?.auditTurnIndex||unit.getId()!==g.__auditJob?.auditUnitId)return;
 assert(!g.__preNativeAudit,"Exactly one registered actual strategy root");
 const {unitRefs,...data}=snapshotBattle(context.unitsHolder,context.grid,context.fightProperties);
 const state=normalize(data),random=captureDeterministicRandomState();
 g.__preNativeAudit={capturePoint:"before-native-strategy",turn:g.__actualTurns.length,unit:unitView(unit),lap:context.fightProperties.getCurrentLap(),
  snapshot:state,snapshotSha256:hash(state),damageStats:null,
  actualTurnPrefixSha256:g.__auditTurnsHash.copy().digest("hex"),eventPrefixSha256:g.__auditEventsHash.copy().digest("hex"),
  liveRandomDrawCount:g.__auditRng.count,liveRandomPrefixSha256:g.__auditRng.hash.copy().digest("hex"),uuidSequence:random.uuidSequence};
};
const pinnedMindless=getAIStrategy(MINDLESS_AI_VERSION) as any,pinnedMindlessDecide=pinnedMindless.decideTurn;
pinnedMindless.decideTurn=function(unit:any,context:any){g.__auditBeforeStrategy(unit,context);return pinnedMindlessDecide.call(this,unit,context);};
proto.chooseDecision = function (unit: any, ...args: any[]) {
    g.__modelActorTeam = unit.getTeam();
    const capture=g.__actualTurns?.length===g.__auditJob?.auditTurnIndex&&unit.getId()===g.__auditJob?.auditUnitId;
    const prior=activeRoot;
    if(capture){
      assert(!g.__rootAudit,"Capture exactly one registered root");
      const snapshot=snapshotBattle(this.deps.unitsHolder,this.deps.grid,this.deps.fightProperties);
      const {unitRefs,...data}=snapshot;
      const state=normalize(data), random=captureDeterministicRandomState();
      activeRoot=g.__rootAudit={capturePoint:"before-A19-after-native",beforeNativeSnapshotSha256:g.__preNativeAudit?.snapshotSha256,turn:g.__actualTurns.length,unit:unitView(unit),lap:this.deps.fightProperties.getCurrentLap(),
       snapshot:state,snapshotSha256:hash(state),damageStats:normalize(this.deps.captureDamageStats()),
       actualTurnPrefixSha256:g.__auditTurnsHash.copy().digest("hex"),eventPrefixSha256:g.__auditEventsHash.copy().digest("hex"),
       liveRandomDrawCount:g.__auditRng.count,liveRandomPrefixSha256:g.__auditRng.hash.copy().digest("hex"),uuidSequence:random.uuidSequence,
       rawIncumbent:structuredClone(args[1]),scoreGroups:[],forecasts:[]};
    }
    try {
      const result = choose.call(this, unit, ...args);
      assert(!g.__forecastFault, `Forecast callback failed: ${g.__forecastFault}`);
      if(capture){activeRoot.chosenDecision=structuredClone(result);activeRoot.materialEvidence=structuredClone(this.a19MaterialEvidence);}
      return result;
    } finally {activeRoot=prior;}
};
proto.rollout = function (unit: any, candidate: any, ...args: any[]) {
    const prior = scope;
    scope = g.__mode !== "stock" && g.__mode !== "accepted" && unit.getTeam() === g.__team
        ? { rootTeam: unit.getTeam(), rootActor: unit.getName(), mode: args[2], candidateKind: candidate.kind, sample: {seedBase:args[0],sampleIndex:args[1],horizonMode:args[2],rolloutCount:this.rollouts} }
        : undefined;
    if (scope && g.__mode === "mixture" && args[2] === "turns") { assert.equal(this.rollouts,2);g.__stats.models[usesBarrelIntentForecast(scope.sample)?"intent":"native"]++; }
    try {
        const priorSample=activeSample;
        if(activeRoot)activeSample={actions:structuredClone(candidate.actions),kind:candidate.kind,seedBase:args[0],sampleIndex:args[1],horizonMode:args[2],turnHorizon:args[4],complementary:args[5],intentModel:!!scope&&usesBarrelIntentForecast(scope.sample),futureTurns:0,firstFutureTurns:[],barrelBoundaries:[]};
        try {
         const value = rollout.call(this, unit, candidate, ...args);
         assert(!g.__forecastFault, `Forecast callback failed: ${g.__forecastFault}`);
         if(activeRoot){activeSample.score=Number.isFinite(value)?value:null;activeSample.finite=Number.isFinite(value);
          activeSample.finishedSim=this.finishedSim;activeSample.winningTeam=this.finishedWinningTeam;activeSample.exactTerminalResults=this.exactTerminalResults;
          activeSample.endLap=this.deps.fightProperties.getCurrentLap();activeSample.units=[...this.deps.unitsHolder.getAllUnits().values()].map(unitView);
          activeRoot.forecasts.push(activeSample);}
         return value;
        } finally {activeSample=priorSample;}
    } finally { scope = prior; }
};
g.__barrelForecastBoundary = (unit: any, context: any, before: any[], cleanup: any[]) => {
    if (!scope) return cleanup;
    try {
        assert.equal(context.decisionOrigin, "rollout", "A projected-turn scope must never change a live native root");
        g.__stats.boundaries++;
        const nativeIntent = selectBarrelForecastIntent(unit, context, before, cleanup);
        const alternative = (g.__mode === "mixture" || g.__mode === "observe") ? selectBarrelForecastModelMixture(unit, context, before, cleanup, scope.sample) : nativeIntent;
        if(activeSample&&nativeIntent!==cleanup)activeSample.barrelBoundaries.push({unit:unitView(unit),lap:context.fightProperties.getCurrentLap(),before:structuredClone(before),cleanup:structuredClone(cleanup),keptIntent:alternative!==cleanup});
        if (nativeIntent !== cleanup) g.__stats.eligible++;
        if (nativeIntent !== cleanup && alternative === cleanup) g.__stats.nativeModelKeptCleanup++;
        if (alternative !== cleanup) {
            g.__stats.changed++;
            const key = unit.getTeam() === scope.rootTeam ? "ownFuture" : "enemyFuture";
            g.__stats[key]++;
            const intent = before.find((a: any) => ["move_unit", "wait_turn", "defend_turn"].includes(a.type)).type;
            g.__stats.intents[intent] = (g.__stats.intents[intent] ?? 0) + 1;
            if (g.__stats.witnesses.length < 8) g.__stats.witnesses.push({ ...scope, actor: unit.getName(), team: unit.getTeam(),
                lap: context.fightProperties.getCurrentLap(), before: structuredClone(before), cleanup: structuredClone(cleanup) });
        }
        return (g.__mode === "forecast" || g.__mode === "mixture") ? alternative : cleanup;
    } catch (error) { g.__forecastFault = String(error); throw error; }
};

const scoreCandidates=proto.scoreCandidates,simPlayTurn=proto.simPlayTurn;
proto.scoreCandidates=function(unit:any,candidates:any[],...args:any[]){
